const spots=window.BITE_BUSINESSES;
const featuredSpots=spots.filter(s=>s.featured!==false);
const initial={xp:0,visits:{},read:[],km:0,boxes:[{id:1,tier:2,start:0,open:false}],tokens:3,claimed:[],offers:[],cooldown:0,onboard:false};let state;try{state={...initial,...JSON.parse(localStorage.getItem('bitequest-v1')||'null')}}catch{state=structuredClone(initial)}if(state.datasetVersion!==3){state.legacyDemoCards=Object.keys(state.visits).length;state.legacyDemoVisits={...state.visits};state.legacyDemoStories=[...state.read];state.visits={};state.read=[];state.claimed=state.claimed.filter(id=>!['first','stories','coffee','dumpling','season'].includes(id));state.datasetVersion=3;}state.wantToTry=Array.isArray(state.wantToTry)?state.wantToTry:[];window.BITE_WALKING.migrate(state);let tab='Explore',filter='All bites',search='',selected=null,mode='demo',position={x:0,y:0},gps=null,zoom=1;const app=document.querySelector('#app'),dialog=document.querySelector('#detail');const icons={Explore:'⌖',Collection:'▧',Quests:'⚑',Lunchboxes:'▣',Profile:'☺'};
function save(){try{localStorage.setItem('bitequest-v1',JSON.stringify(state))}catch{toast('Progress could not be saved on this device.')}if(document.querySelector('#explorerRank'))document.querySelector('#explorerRank').textContent=window.BITE_CONTENT.rank(state.xp);document.querySelector('#xp').textContent=`LEVEL ${1+Math.floor(state.xp/500)} · ${state.xp} XP`}
function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3500)}
function go(t){tab=t;render()}
function render(){window.biteWorld?.dispose();window.biteWorld=null;document.body.classList.toggle('exploring',tab==='Explore');save();document.querySelector('#nav').innerHTML=Object.keys(icons).map(t=>`<button class="${t===tab?'active':''}" data-tab="${t}" aria-current="${t===tab?'page':'false'}"><span class="nav-icon">${icons[t]}</span>${t}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-label',b.dataset.tab));if(tab==='Explore')explore();else if(tab==='Collection')collection();else if(tab==='Quests')quests();else if(tab==='Lunchboxes')lunchboxes();else profile();window.BITE_PASSPORT?.hydrate()}
function mapSVG(){let streets='';for(let x=210;x<860;x+=46)streets+=`<path d="M${x} 0 L${x-130} 820"/>`;for(let y=-50;y<850;y+=43)streets+=`<path d="M50 ${y} L940 ${y+150}"/>`;return `<svg viewBox="0 0 1000 820" preserveAspectRatio="xMidYMid slice" aria-label="Illustrated Lower Manhattan map"><defs><clipPath id="land"><path d="M170 -50 L970 -50 935 240 838 530 705 680 512 820 352 779 219 635 110 399 112 186Z"/></clipPath></defs><rect width="1000" height="820" fill="#bbddda"/><g clip-path="url(#land)"><rect width="1000" height="820" fill="#e7ead9"/><g fill="#d9dfc9" stroke="#d0d8bf" stroke-width="2"><path d="M190 310h155v98H190zM630 120h139v90H630zM479 597h116v83H479zM390 29h97v111H390z"/></g><g stroke="#faf9ee" stroke-width="11" fill="none">${streets}</g><g stroke="#c9d4b9" stroke-width="2" fill="none">${streets}</g><path d="M635 -30L580 270 506 470 390 820" stroke="#fcfbf2" stroke-width="21" fill="none"/><path d="M635 -30L580 270 506 470 390 820" stroke="#eddbb4" stroke-width="8" fill="none"/><path d="M160 432Q480 420 861 483" stroke="#fffdf3" stroke-width="20" fill="none"/></g><path d="M725 670L1060 763" stroke="#f6f3df" stroke-width="19"/><path d="M838 530L1090 546" stroke="#f6f3df" stroke-width="16"/><g class="map-label"><text x="320" y="203">SOHO</text><text x="562" y="167">NOLITA</text><text x="711" y="315">LOWER</text><text x="709" y="338">EAST SIDE</text><text x="515" y="399">CHINATOWN</text><text x="242" y="550">TRIBECA</text><text x="460" y="704">CIVIC CENTER</text></g><g class="street-label"><text x="435" y="459" transform="rotate(8 435 459)">CANAL STREET</text><text x="520" y="300" transform="rotate(-72 520 300)">BROADWAY</text><text x="811" y="652" transform="rotate(16 811 652)">MANHATTAN BRIDGE</text><text x="87" y="670" transform="rotate(-70 87 670)" fill="#5faaa6">HUDSON RIVER</text><text x="826" y="720" fill="#5faaa6">EAST RIVER</text></g></svg>`}
function matches(s){return (filter==='All bites'||s.type===filter||s.cuisine===filter)&&(!search||`${s.name} ${s.cuisine} ${s.area}`.toLowerCase().includes(search.toLowerCase()))}
function foodArt(s){const a=window.BITE_CONTENT.foodArt[s.id]||{path:'food-atlas.png',slot:0};return `<span class="food-art" style="--food-inset:${a.aspect===1?'0':'-25% 0'};--food-atlas:url('${a.path}');background-position:${a.slot%3*50}% ${Math.floor(a.slot/3)*100}%" role="img" aria-label="Illustrated ${s.cuisine} food"></span>`}
function listSpots(list){return list.map(s=>`<button class="spot" data-spot="${s.id}"><span class="spot-icon">${foodArt(s)}</span><span><b>${s.name} ${state.visits[s.id]?'✓':''}</b><small>${s.cuisine} · ${s.area} · ${s.price}</small></span><span class="arrow">↗</span></button>`).join('')||'<p class="muted">No businesses match. Clear the filter to find Wa Lung Kitchen on Grand Street.</p>'}
function explore(){
app.innerHTML=`<section class="world-shell" aria-label="Interactive 3D Bite Quest map"><div id="world"><div class="world-loading">Loading New York’s streets and buildings…</div></div><div class="map-print" aria-hidden="true"></div><div class="world-vignette" aria-hidden="true"></div><div class="world-hud"><div class="district"><span class="eyebrow">NEW YORK CITY</span><h1>Lower East Side</h1></div><button class="quest-pill" id="questHud"><span>⚑</span><div><small>THREE CUISINES</small><b>${Math.min(window.BITE_CONTENT.firstGoal,countryBadges().length)} / ${window.BITE_CONTENT.firstGoal} cuisines discovered</b><div class="progress"><i style="width:${Math.min(100,countryBadges().length/window.BITE_CONTENT.firstGoal*100)}%"></i></div></div><span>›</span></button></div><div class="world-tools"><button class="tool-button compass" id="recenter" aria-label="Recenter map"><span>N</span>➤</button><button class="tool-button" id="locate" aria-label="Location settings">◎</button><button class="tool-button" id="zoomIn" aria-label="Zoom in">＋</button><button class="tool-button" id="zoomOut" aria-label="Zoom out">−</button><button class="tool-button" id="worldHelp" aria-label="How to play">?</button></div><div class="map-dock"><div class="stats-strip"><span><img class="owl-portrait" src="rat-chef.png" alt="Rat chef explorer"> <b>Lv. ${1+Math.floor(state.xp/500)}</b> · ${state.xp} XP</span><button class="carrier-pill" id="boxShortcut"><b id="carrierProgress">${state.km.toFixed(1)} km explored</b><span> ›</span></button></div><div class="world-bottom"><div class="next-bite"><button class="primary" id="next">Find my next bite <span>↗</span></button></div><button class="nearby-pill" id="nearby"><span>Nearby bites <b>${featuredSpots.length}</b>⌃</span></button></div></div><div class="world-instructions"><span class="desktop-hint">Drag to rotate · Scroll to zoom · </span>Tap a street to walk · Tap a bite to discover <button type="button" aria-label="Dismiss map hint" onclick="this.parentElement.hidden=true">×</button></div><button class="world-disclaimer map-source" id="mapSources" aria-label="About this map and data attribution">ⓘ About this map</button></section>`;
app.querySelector('#next').onclick=()=>openSpot((featuredSpots.find(s=>!state.visits[s.id]&&s.countryCodes.some(c=>!countryBadges().includes(c)))||featuredSpots.find(s=>!state.visits[s.id])||featuredSpots[0]).id);app.querySelector('#questHud').onclick=()=>go('Quests');app.querySelector('#locate').onclick=locationInfo;app.querySelector('#boxShortcut').onclick=()=>go('Lunchboxes');app.querySelector('#nearby').onclick=nearbyBites;app.querySelector('#worldHelp').onclick=worldHelp;app.querySelector('#mapSources').onclick=mapSources;app.querySelector('#recenter').onclick=()=>window.biteWorld?.recenter();app.querySelector('#zoomIn').onclick=()=>window.biteWorld?.zoom(-1);app.querySelector('#zoomOut').onclick=()=>window.biteWorld?.zoom(1);
window.BiteQuestBridge={spots:featuredSpots,focusId:selected,position:{...position},collected:Object.keys(state.visits),open:openSpot,stop,move(p,km){if(mode!=='demo'){toast('Switch to Demo Mode to walk through this illustrated world.');return false}position=p;state.km+=km;save();const counter=document.querySelector('#carrierProgress');if(counter)counter.textContent=state.km.toFixed(2)+' km explored';return true;}};
window.dispatchEvent(new Event('bitequest:mount'));
}
function nearbyBites(){modal(`<div class="detail-body">${closeButton()}<span class="eyebrow">AROUND THE CORNER</span><h2>A new cuisine, a block away.</h2><input class="search" id="nearSearch" placeholder="A cuisine, a neighborhood, a craving…" aria-label="Search nearby bites"><div class="chips">${['All bites','Coffee','Dumplings','Bakery'].map(t=>`<button class="chip ${filter===t?'active':''}" data-nfilter="${t}">${t}</button>`).join('')}<button class="chip" id="moreFilters">More filters</button></div><div id="nearResults">${listSpots(featuredSpots.filter(matches))}</div><p class="fine">Meet the business behind the bite. Save a kitchen, read its story, then try its food. Our starter list does not measure TikTok popularity.</p></div>`);bindSpots();document.querySelector('#nearSearch').value=search;document.querySelector('#nearSearch').oninput=e=>{search=e.target.value;document.querySelector('#nearResults').innerHTML=listSpots(featuredSpots.filter(matches));bindSpots()};document.querySelectorAll('[data-nfilter]').forEach(b=>b.onclick=()=>{filter=b.dataset.nfilter;nearbyBites()});document.querySelector('#moreFilters').onclick=filters}
function worldHelp(){modal(`<div class="detail-body story-screen">${closeButton()}<h2>Find the kitchen a block away.</h2><p>Meet an independent business, read its story, and log your first bite from its cuisine to earn a cuisine stamp. Three cuisines complete your starter trail.</p><p>Zoom out to group nearby bites. Tap a rounded group to reveal its restaurants. Tap a food marker. Choose “I ate here — log this bite,” then toss the token. Demo visits are simulated.</p><p>Tap streets or use arrow keys to walk. Drag to orbit, shift-drag to pan, and pinch or scroll to zoom.</p><p>Save places you want to try. Share the business with a friend. Cuisine stamps and completed trails are the main collection; XP is a bonus.</p><button class="primary wide" id="helpMission">Why Bite Quest?</button><button class="secondary wide" data-close>Back to the neighborhood</button></div>`);document.querySelector('#helpMission').onclick=onboard}

function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function bindSpots(){document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>openSpot(b.dataset.spot))}function modal(html){dialog.classList.remove('catch-dialog');dialog.innerHTML=html;if(!dialog.open)dialog.showModal();dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());window.BITE_PASSPORT?.hydrate()}function closeButton(){return '<button class="close" data-close aria-label="Close">×</button>'}function cuisines(){return [...new Set(Object.keys(state.visits).map(id=>spots.find(s=>s.id===id)?.cuisine).filter(Boolean))]}
function openSpot(id){let s=spots.find(s=>s.id===id);if(!s)return;selected=id;let visits=state.visits[id]||0;modal(`<div class="detail-art">${foodArt(s)}<span class="art-caption">Food illustration · not a restaurant photo</span>${closeButton()}</div><div class="detail-body"><span class="eyebrow">${visits?'IN YOUR COLLECTION':'A NEW BITE AWAITS'}</span><h2>${s.name}</h2><p class="muted">${s.cuisine} · ${s.area}${s.price==='Not checked'?'':' · '+s.price}</p><span class="tag">${s.tag}</span><span class="tag">${s.diet}</span><h3>${s.dish}</h3><p>${s.dishStory||s.story}</p><div class="badge-grant">${s.countryCodes.length?s.countryCodes.map(countryLink).join(''):'A neighborhood coffee stop. Save it for your next walk.'}</div><div class="real-business-info"><b>${s.address}, New York, NY ${s.postalCode||'10002'}</b><p class="fine">${s.why}</p><div class="controls"><a class="secondary" href="${s.source}" target="_blank" rel="noopener">${s.sourceLabel} ↗</a><a class="secondary" href="${s.menu}" target="_blank" rel="noopener">Website / menu ↗</a><a class="secondary" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.name+' '+s.address+' New York NY')}" target="_blank" rel="noopener">Directions ↗</a></div><p class="fine">Menu and pricing may change. Check the business website before visiting. Independent listing; no partnership is implied.</p></div><button class="secondary wide" id="readStory">${state.read.includes(id)?'✓ Story discovered':'Discover their story · +25 XP'}</button><p class="fine">${visits} logged bites · Finding the business and reading its story earns exploration XP. A logged dining visit earns the cuisine stamp.</p><button class="secondary wide" id="mapFocus">Show this business on the 3D map ⌖</button><div class="controls"><button class="secondary" id="saveSpot">${state.wantToTry.includes(id)?'✓ Saved to Want to try':'Want to try'}</button><button class="secondary" id="sendSpot">Send to a friend</button></div><button class="primary wide" id="visit">${mode==='demo'?'I ate here — log this bite':'Visit verification'}</button><p class="fine">Demo visits are simulated. In a partner launch, a merchant QR code would verify dining; GPS alone cannot.</p></div>`);bindCountries();document.querySelector('#saveSpot').onclick=()=>{state.wantToTry=state.wantToTry.includes(id)?state.wantToTry.filter(x=>x!==id):[...state.wantToTry,id];save();openSpot(id)};document.querySelector('#sendSpot').onclick=()=>businessShare(s);document.querySelector('#readStory').onclick=()=>{if(!state.read.includes(id)){state.read.push(id);state.xp+=25;save();toast('+25 XP · A story worth discovering')}openSpot(id)};document.querySelector('#mapFocus').onclick=()=>{dialog.close();if(tab==='Explore')window.biteWorld?.focus(id);else go('Explore')};document.querySelector('#visit').onclick=()=>{if(mode!=='demo'){toast('No merchant verification partners yet. Switch to Demo Mode to collect.');return}startCatchStage(id)}}

function catchSpot(id){const s=spots.find(s=>s.id===id);if(mode!=='demo'||!s)return;const before=countryBadges(),oldTitles=window.BITE_CONTENT.trails.filter(t=>window.BITE_CONTENT.progress(t,state,spots).done).map(t=>t.id);state.visits[id]=(state.visits[id]||0)+1;state.xp+=100;save();render();const fresh=s.countryCodes.filter(c=>!before.includes(c)),titles=window.BITE_CONTENT.trails.filter(t=>!oldTitles.includes(t.id)&&window.BITE_CONTENT.progress(t,state,spots).done);modal(`<div class="celebrate story-screen">${closeButton()}<span class="eyebrow">${fresh.length?'CUISINE STAMP UNLOCKED':'BITE LOGGED'}</span>${fresh.length?fresh.map(c=>badgeToken(c,true)).join(''):`<span class="big">${foodArt(s)}</span>`}<h2>${fresh.length?fresh.map(countryName).join(' + '):s.name}</h2><p><strong>${s.signatureDish}</strong><br>at ${s.name} · ${s.area}</p>${s.countryCodes.map(c=>`<p>${rarityText(c)}${before.includes(c)?' · Badge already earned':''}</p>`).join('')}${!s.countryCodes.length?'<p>No cuisine stamp assigned to this cuisine yet. Your business visit still counts.</p>':''}<p>${Math.min(window.BITE_CONTENT.firstGoal,countryBadges().length)} / ${window.BITE_CONTENT.firstGoal} cuisines · Three Cuisines, One City</p>${titles.map(t=>`<p><strong>Trail complete: ${t.name}</strong><br>Title earned: ${t.reward}</p>`).join('')}<p class="fine">+100 XP · Demo dining log. Rarity labeled demo is illustrative, not a NYC census.</p><button class="primary wide" id="continue">Keep exploring</button><button class="secondary wide" id="viewCollection">View food passport</button><button class="secondary wide" id="unlockShare">Send ${s.name} to a friend</button></div>`);document.querySelector('#continue').onclick=()=>dialog.close();document.querySelector('#viewCollection').onclick=()=>{dialog.close();go('Collection')};document.querySelector('#unlockShare').onclick=()=>businessShare(s)}
function walk(){if(mode!=='demo')return;state.km+=.5;save();render();toast(`Demo walk +0.5 km · ${state.km.toFixed(1)} km explored`)}
document.querySelector('#profileShortcut').onclick=()=>go('Profile');render();
function filters(){modal(`<div class="detail-body">${closeButton()}<h2>Find your flavor</h2><p class="muted">Filter the researched business list. Unverified accessibility and pricing remain unknown; check with the business before visiting.</p><div class="controls"><label>Cuisine <select id="fCuisine"><option>Any</option>${[...new Set(featuredSpots.map(s=>s.cuisine))].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Budget guide <select id="fPrice"><option>Any</option><option>$</option><option>$$</option><option>Not checked</option></select></label><label>Dietary options <select id="fDiet"><option>Any</option><option>Vegan options</option><option>Vegetarian options</option></select></label><label>Business story <select id="fTag"><option>Any</option>${[...new Set(featuredSpots.map(s=>s.tag))].map(s=>`<option>${s}</option>`).join('')}</select></label><label><input type="checkbox" id="fAccess"> Confirmed step-free entrance</label></div><button class="primary wide" id="applyFilters">Show matching bites</button></div>`);document.querySelector('#applyFilters').onclick=()=>{let c=document.querySelector('#fCuisine').value,p=document.querySelector('#fPrice').value,d=document.querySelector('#fDiet').value,t=document.querySelector('#fTag').value,a=document.querySelector('#fAccess').checked;let list=featuredSpots.filter(s=>(c==='Any'||c===s.cuisine)&&(p==='Any'||p===s.price)&&(d==='Any'||d===s.diet)&&(t==='Any'||t===s.tag)&&(!a||s.access));modal(`<div class="detail-body">${closeButton()}<h2>Your kind of bites</h2><p class="muted">${list.length} businesses match your preferences.</p>${listSpots(list)}<button class="secondary wide" id="editFilters">Adjust filters</button></div>`);bindSpots();document.querySelector('#editFilters').onclick=filters}}
function onboard(){const m=window.BITE_CONTENT.mission;modal(`<div class="detail-body story-screen">${closeButton()}<span class="eyebrow">BITE QUEST · NEW YORK</span><h2>${m.heading}</h2><p>${m.intro}</p><h3>${m.goal}</h3><p>${m.body}</p><p><strong>Your first goal: Three Cuisines, One City.</strong><br>Log bites from three cuisines. Start with Wa Lung Kitchen’s Cantonese dumplings, Café Katja’s Austrian cooking, or Patacon Pisao’s Venezuelan plantain sandwiches.</p><button class="primary wide" id="startDemo">Find my first cuisine</button><button class="secondary wide" id="enableGPS">Use my location</button><p class="fine">${featuredSpots.length} featured businesses to start. Dining and map movement are simulated. Lunchboxes require GPS-tracked walking. Rarity counts are demo estimates. Other cuisine stamps need researched listings.</p></div>`);const finish=()=>{state.storyIntroVersion=window.BITE_CONTENT.version;state.onboard=true;save()};document.querySelector('#startDemo').onclick=()=>{finish();mode='demo';dialog.close();render()};document.querySelector('#enableGPS').onclick=()=>{finish();useLocation()};dialog.querySelector('[data-close]').onclick=()=>{finish();dialog.close()}}

function locationInfo(){modal(`<div class="detail-body">${closeButton()}<h2>Your adventure, your pace.</h2><p>Demo Mode lets you browse the map and simulate dining. It cannot advance lunchboxes.</p><p class="muted">Location mode reads your current position only when you ask. This map uses NYC building footprints and OpenStreetMap streets. Start foreground walking from Lunchboxes. Background tracking and real offer redemption are not connected.</p>${gps?`<p class="fine">Location accuracy: approximately ${Math.round(gps.accuracy)} meters. Precise coordinates are not saved.</p>`:''}<button class="primary wide" id="gps">Use my current location</button><button class="secondary wide" id="demoMode">Switch to Demo Mode</button></div>`);document.querySelector('#gps').onclick=useLocation;document.querySelector('#demoMode').onclick=()=>{mode='demo';gps=null;dialog.close();render();toast('Demo Mode is on')};}
function useLocation(){if(!navigator.geolocation){toast('Location is unavailable. Demo Mode is ready.');return}toast('Waiting for location permission…');navigator.geolocation.getCurrentPosition(p=>{gps=p.coords;mode='gps';state.onboard=true;dialog.close();render();const near=Math.abs(gps.latitude-40.718)<.05&&Math.abs(gps.longitude+74)<.06;toast(near?'Location received. Business pins use NYC address coordinates.':'You’re outside Lower Manhattan. Use Demo Mode to explore.');},()=>{mode='demo';toast('Location unavailable or declined. You can keep exploring in Demo Mode.')},{enableHighAccuracy:true,timeout:10000,maximumAge:30000})}
function stop(){let remain=Math.max(0,Math.ceil((state.cooldown-Date.now())/1000));modal(`<div class="celebrate">${closeButton()}<span class="eyebrow">DEMO BITE STOP</span><img class="stop-poster" src="retro-sign.png" alt="Original illustrated Bite Quest New York discovery poster"><h2>Sara D. Roosevelt Park discovery stop</h2><p class="muted">In the live game, approach within 75 m from a public walkway. Demo Mode simulates proximity.</p><p>Spin for a lunchbox and 3 Bite Tokens.</p><button class="primary wide" id="spin" ${remain||mode!=='demo'?'disabled':''}>${remain?`Ready in ${remain} seconds`:mode==='demo'?'Spin the Bite Stop':'Switch to Demo Mode to spin'}</button><p class="fine">60-second cooldown · No real-world stop is installed.</p></div>`);document.querySelector('#spin').onclick=()=>{if(Date.now()<state.cooldown||mode!=='demo')return;const tier=[2,5,10][state.boxes.length%3];state.boxes.push({id:Date.now(),tier,start:state.km,walkingStart:state.walkingKm,open:false});state.tokens+=3;state.cooldown=Date.now()+60000;save();dialog.close();render();toast(`${tier} km lunchbox + 3 Bite Tokens added!`)}}
function collection(){const earned=countryBadges(),all=window.BITE_CONTENT.countries,rarest=earned.slice().sort((a,b)=>window.BITE_CONTENT.rarityFor(b).rank-window.BITE_CONTENT.rarityFor(a).rank)[0];app.innerHTML=`<section class="page story-screen"><span class="eyebrow">YOUR CITY. YOUR TASTE. YOUR FINDS.</span><h1>Your food passport</h1><p>${earned.length} cuisine ${earned.length===1?'badge':'badges'} · ${Object.keys(state.visits).length} ${Object.keys(state.visits).length===1?'business':'businesses'} discovered.</p><p>${rarest?`Rarest earned: ${countryName(rarest)} · ${rarityText(rarest)}`:'Your first cuisine is a meal away. Try Cantonese dumplings at Wa Lung Kitchen on Grand Street.'}</p><div class="controls"><button class="primary" id="share">Share my passport</button><button class="secondary" id="wantList">Want to try (${state.wantToTry.length})</button></div><input class="search" id="collectionSearch" placeholder="Search a cuisine" aria-label="Search cuisine stamps"><div class="controls"><label>Show <select id="badgeFilter"><option value="earned">Earned badges</option><option value="available">Available nearby</option><option value="all">All ${all.length} cuisine directory entries</option></select></label><label>Order <select id="sort"><option value="name">Cuisine name</option><option value="rarity">Rarest first</option></select></label></div><details class="coverage-note"><summary>About rarity and listing coverage</summary><p>Rarity counts are labeled demo estimates or not assessed. They are not a verified NYC inventory. Locked badges do not imply a local restaurant is available.</p></details><div id="cards" class="grid badge-grid"></div><h2>Trails in progress</h2><div class="grid">${window.BITE_CONTENT.trails.filter(t=>{const p=window.BITE_CONTENT.progress(t,state,spots);return p.have>0&&!p.done||t.id==='first-countries'}).slice(0,3).map(trailCard).join('')}</div><h2>The stories behind my stamps</h2>${spots.filter(s=>state.visits[s.id]).map(discoveryCard).join('')||`<p>Your first food story starts with Wa Lung Kitchen. Meet the kitchen, then make it part of your passport.</p><button class="secondary" data-spot="walung">Meet Wa Lung Kitchen</button>`}</section>`;const draw=()=>{const query=document.querySelector('#collectionSearch').value.toLowerCase(),filter=document.querySelector('#badgeFilter').value;let list=all.filter(c=>(countryName(c.code)+' '+c.name).toLowerCase().includes(query)&&(filter==='all'||(filter==='available'?featuredSpots.some(s=>s.countryCodes.includes(c.code)):earned.includes(c.code))));list.sort((a,b)=>document.querySelector('#sort').value==='rarity'?window.BITE_CONTENT.rarityFor(b.code).rank-window.BITE_CONTENT.rarityFor(a.code).rank||countryName(a.code).localeCompare(countryName(b.code)):countryName(a.code).localeCompare(countryName(b.code)));document.querySelector('#cards').innerHTML=list.map(c=>`<button class="card badge-card" data-country="${c.code}">${badgeToken(c.code,earned.includes(c.code))}<strong>${countryName(c.code)}</strong><span>${earned.includes(c.code)?'✓ Earned':'Not earned'}</span><span class="rarity-label">${rarityText(c.code)}</span><small>${spots.some(s=>s.countryCodes.includes(c.code))?'Business listed nearby':'Listing needed'}</small></button>`).join('')||`<div class="card"><h2>${query?'No matching badges':'Your first badge starts on Grand Street.'}</h2><p>${query?'Try another cuisine name, or choose All cuisine directory entries.':'Try dumplings at Wa Lung Kitchen. Your first logged Cantonese bite unlocks the Chinese Food stamp.'}</p><button class="primary" data-spot="walung">Meet Wa Lung Kitchen</button></div>`;bindCountries();bindSpots();window.BITE_PASSPORT?.hydrate()};document.querySelector('#badgeFilter').value=earned.length?'earned':'available';draw();document.querySelector('#collectionSearch').oninput=draw;document.querySelector('#badgeFilter').onchange=draw;document.querySelector('#sort').onchange=draw;document.querySelector('#share').onclick=shareCollection;document.querySelector('#wantList').onclick=wantList;bindSpots();bindTrails();bindDiscoveryShares()}

async function shareCollection(){sharePreview('collection',spots.find(s=>state.visits[s.id])||spots.find(s=>state.wantToTry.includes(s.id))||spots[0])}
function discoveryCard(s){return `<article class="discovery-story"><div class="discovery-picture">${foodArt(s)}</div><div><span class="eyebrow">${state.visits[s.id]?'FROM MY FOOD PASSPORT':'ON MY LIST'} · ${s.area}</span><h3>${s.name}</h3><p><strong>${s.signatureDish}</strong></p><p>${s.story}</p><div class="controls"><button class="secondary" data-spot="${s.id}">Meet the kitchen</button><button class="primary" data-discovery-share="${s.id}">Share this find</button></div></div></article>`}
function bindDiscoveryShares(){document.querySelectorAll('[data-discovery-share]').forEach(b=>b.onclick=()=>businessShare(spots.find(s=>s.id===b.dataset.discoveryShare)))}

const questDefs=[{id:'first',kind:'STARTER',name:'Three Cuisines, One City',desc:'Log bites from three different cuisines.',goal:window.BITE_CONTENT.firstGoal,xp:150,count:()=>countryBadges().length},{id:'stories',kind:'DAILY · NO STREAK REQUIRED',name:'Meet the neighborhood',desc:'Discover three restaurant stories.',goal:3,xp:100,count:()=>state.read.length},{id:'coffee',kind:'WEEKLY',name:'A cup around the corner',desc:'Explore Black Cat LES with a simulated visit.',goal:1,xp:75,count:()=>state.visits.blackcat?1:0},{id:'dumpling',kind:'NEIGHBORHOOD',name:'A Cantonese classic',desc:'Collect Wa Lung Kitchen with a simulated visit.',goal:1,xp:75,count:()=>state.visits.walung?1:0},{id:'season',kind:'SEASONAL · FALL EXPLORATION',name:'A taste of somewhere new',desc:'Discover six businesses in this neighborhood collection.',goal:6,xp:200,count:()=>Object.keys(state.visits).length}];
function quests(){app.innerHTML=`<section class="page story-screen"><span class="eyebrow">LET THE BADGES ADD UP TO SOMETHING</span><h1>Your city trails</h1><p>Follow cuisines, ingredients, and neighborhood kitchens. Each completed trail adds a title to your profile.</p>${window.BITE_CONTENT.trails.some(t=>window.BITE_CONTENT.progress(t,state,spots).done)?'':`<p>No trails complete yet. Start Three Cuisines, One City with Wa Lung Kitchen, Café Katja, and Patacon Pisao.</p>`}<div class="grid">${window.BITE_CONTENT.trails.map(trailCard).join('')}</div><h2>Extra exploration rewards</h2><p>XP is a bonus. Stories, visits, and your existing rewards still count.</p><div class="grid">${questDefs.map(q=>{const n=Math.min(q.goal,q.count()),done=state.claimed.includes(q.id);return `<article class="card"><h3>${q.name}</h3><p>${q.desc}</p><p>${n} / ${q.goal} · +${q.xp} XP</p><button class="secondary" data-claim="${q.id}" ${done?'disabled':''}>${done?'Reward claimed':n===q.goal?'Claim XP reward':'Explore to progress'}</button></article>`}).join('')}</div><article class="card"><h2>A little food trivia</h2><p>Which ingredient gives za’atar its tangy flavor?</p><div class="controls">${['Sumac','Cinnamon','Vanilla'].map(a=>`<button class="secondary" data-answer="${a}">${a}</button>`).join('')}</div></article></section>`;bindTrails();document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>toast(b.dataset.answer==='Sumac'?'Correct! Sumac brings that bright, tart flavor.':'Try again. Think bright, tart, and deep red.'));document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{const q=questDefs.find(q=>q.id===b.dataset.claim);if(q.count()<q.goal){go('Explore');return}if(state.claimed.includes(q.id))return;state.claimed.push(q.id);state.xp+=q.xp;render();toast(`Exploration reward · +${q.xp} XP`)})}

let walkingWatch=null,walkingStatus='Start a walk to count distance toward your lunchboxes.';const walkTracker=window.BITE_WALKING.tracker();
function pauseWalking(message='Walk paused. Your distance is saved.'){if(walkingWatch!==null)navigator.geolocation.clearWatch(walkingWatch);walkingWatch=null;walkTracker.reset();walkingStatus=message;if(tab==='Lunchboxes')lunchboxes();}
function startWalking(){if(!navigator.geolocation){walkingStatus='This browser cannot track location. Open Bite Quest on a phone with GPS.';lunchboxes();return}walkingStatus='Waiting for location permission and a clear GPS signal…';lunchboxes();walkingWatch=navigator.geolocation.watchPosition(p=>{if(document.hidden){walkTracker.reset();return}const km=walkTracker.sample(p);if(km>0){state.walkingKm+=km;save()}walkingStatus=p.coords.accuracy>window.BITE_WALKING.config.maxAccuracyM?'GPS signal is weak. Distance will count when accuracy improves.':'Walk tracking is on. Keep Bite Quest open while you walk.';if(tab==='Lunchboxes')lunchboxes();},e=>pauseWalking(e.code===1?'Location permission is needed to count your walk. Enable it in your browser settings.':'GPS is unavailable. Move outdoors and start your walk again.'),{enableHighAccuracy:true,maximumAge:0,timeout:20000});if(tab==='Lunchboxes')lunchboxes();}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&walkingWatch!==null)pauseWalking('Walk paused while the app was hidden. Start again when you return.');});
function lunchboxArt(){return `<img class="lunchbox-art" src="${window.BITE_WALKING.config.art}" alt="Simple rectangular teal school lunchbox with a handle and snap closure">`}
function lunchboxes(){app.innerHTML=`<section class="page lunchbox-page"><span class="eyebrow">WALK THE CITY. OPEN SOMETHING GOOD.</span><h1>Your lunchboxes</h1><p class="lunchbox-intro">Walk to unlock lunchboxes filled with reasons to try a new place: discounts on certain days, buy-one-get-one offers, and other restaurant incentives. Every box gives you another reason to step inside a neighborhood kitchen.</p><p class="fine">Offer previews for now: no restaurant offers are redeemable yet. Only GPS-tracked walking unlocks boxes. Map movement and stories do not count.</p><div class="walk-panel"><div><strong>${state.walkingKm.toFixed(2)} km walked</strong><p role="status">${walkingStatus}</p></div><button class="primary" id="trackWalk">${walkingWatch!==null?'Pause walk':'Start walking'}</button></div><div class="controls"><button class="secondary" id="newBox">Visit a Bite Stop</button><button class="secondary" id="wallet">Offer wallet (${state.offers.length})</button></div><div class="grid lunchbox-grid">${state.boxes.map(b=>{const distance=window.BITE_WALKING.progress(state,b),ready=distance>=b.tier;return `<article class="card lunchbox-card">${lunchboxArt()}<span class="eyebrow">${b.tier===2?'EVERYDAY':b.tier===5?'EXPLORER':'ADVENTURE'}</span><h2>${b.tier} km lunchbox</h2><p>${b.tier===2?'Preview a day-specific café discount.':b.tier===5?'Preview a buy-one-get-one offer to share.':'Unlock a golden card frame for your collection.'}</p><progress value="${b.open?b.tier:distance}" max="${b.tier}" aria-label="${b.tier} kilometer lunchbox walking progress"></progress><p>${b.open?'Rewards collected':`${distance.toFixed(2)} / ${b.tier} km walked`}</p><button class="${ready&&!b.open?'primary':'secondary'} wide" data-open="${b.id}" ${b.open||!ready?'disabled':''}>${b.open?'Already opened':ready?'Open lunchbox':'Keep walking'}</button></article>`}).join('')}</div><p class="fine">Keep the app open while walking. Tracking pauses when you leave it. Only total distance is saved, not your route. Earlier simulated distance stays in your profile but does not unlock unopened lunchboxes.</p></section>`;document.querySelector('#trackWalk').onclick=()=>walkingWatch!==null?pauseWalking():startWalking();document.querySelector('#newBox').onclick=stop;document.querySelector('#wallet').onclick=wallet;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openBox(Number(b.dataset.open)))}
function openBox(id){let b=state.boxes.find(b=>b.id===id);if(!b||b.open||window.BITE_WALKING.progress(state,b)<b.tier)return;b.open=true;state.xp+=b.tier*25;let reward=b.tier===10?'Golden Bite Card frame':b.tier===5?'Sample BOGO coffee':'Sample Tuesday café discount — 10% off';state.offers.push({id:b.id,reward,cosmetic:b.tier===10,used:false});save();render();modal(`<div class="celebrate lunchbox-reveal">${closeButton()}<span class="eyebrow">YOU WALKED. YOU UNLOCKED IT.</span>${lunchboxArt()}<h2>A little delicious surprise.</h2><p>+${b.tier*25} XP</p><p><b>${reward}</b></p><p class="fine">${b.tier===10?'A cosmetic added to your wallet.':'Sample offer only. Not valid at any restaurant.'}</p><button class="primary wide" id="rewardWallet">See my rewards</button></div>`);document.querySelector('#rewardWallet').onclick=wallet}
function wallet(){modal(`<div class="detail-body">${closeButton()}<span class="eyebrow">YOUR REWARDS</span><h2>Offer wallet</h2>${state.offers.length?state.offers.map(o=>`<article class="card" style="margin-top:12px"><h3>${o.reward}</h3><p class="fine">${o.cosmetic?'Demo cosmetic earned through exploration.':'SAMPLE ONLY · Not redeemable.<br>Illustrative terms: one per customer, dine-in only, valid 30 days from issue in a future partner program. No participating merchant or expiration date has been issued.'}</p><span class="tag">${o.cosmetic?'Collected':'Sample offer'}</span></article>`).join(''):'<p class="muted">Open a lunchbox to find your first reward.</p>'}</div>`)}
function profile(){const badges=countryBadges(),titles=window.BITE_CONTENT.trails.filter(t=>window.BITE_CONTENT.progress(t,state,spots).done).map(t=>t.reward),level=1+Math.floor(state.xp/500);app.innerHTML=`<section class="page story-screen"><span class="eyebrow">YOUR RELATIONSHIP WITH NEW YORK</span><h1>${window.BITE_CONTENT.rank(state.xp)}</h1><p>${badges.length} ${badges.length===1?'cuisine':'cuisines'} at your table. ${Object.keys(state.visits).length} ${Object.keys(state.visits).length===1?'business':'businesses'} you have found.</p><div class="controls"><button class="primary" id="profileShare">Share my passport</button><button class="secondary" id="profileSaved">Want to try (${state.wantToTry.length})</button></div><div class="grid"><article class="card"><h2>Your cuisine stamps</h2><p>${badges.length?badges.map(countryName).join(' · '):'Start with Austrian cooking at Café Katja on Orchard Street.'}</p><button class="secondary" id="profileBadges">Open food passport</button></article><article class="card"><h2>Titles earned through trails</h2>${titles.length?titles.map(t=>`<p>✓ ${t}</p>`).join(''):'<p>Earn Three-Cuisine Explorer by logging bites from three different cuisines.</p>'}</article><article class="card"><img class="owl-portrait" src="rat-chef.png" alt="Rat chef explorer"><h2>Level ${level} · ${window.BITE_CONTENT.rank(state.xp)}</h2><p>${state.xp%500} / 500 XP to the next level</p><progress value="${state.xp%500}" max="500" aria-label="Level progress"></progress><p>${state.km.toFixed(1)} demo km · ${state.tokens} Bite Tokens</p></article></div><div class="controls"><button class="secondary" id="profileWallet">Offer wallet</button><button class="secondary" id="profileLocation">Location & Demo Mode</button><button class="secondary" id="missionAgain">Why Bite Quest?</button></div><p>Send friends to the business that earned your badge. Compare your passports together.</p><p class="fine">Progress and saved places stay on this device. Shareable passport images and restaurant links are ready to send. There are no connected friend accounts, races, or verified dining yet.</p></section>`;document.querySelector('#profileShare').onclick=shareCollection;document.querySelector('#profileSaved').onclick=wantList;document.querySelector('#profileBadges').onclick=()=>go('Collection');document.querySelector('#profileWallet').onclick=wallet;document.querySelector('#profileLocation').onclick=locationInfo;document.querySelector('#missionAgain').onclick=onboard}

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_bite_encounter',title:'Open a Bite Quest discovery',description:'Open a researched real-business encounter; game visits are simulated. Does not verify dining or collect a card.',inputSchema:{type:'object',properties:{restaurantId:{type:'string',enum:spots.map(s=>s.id)}},required:['restaurantId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.restaurantId!=='string'||!spots.some(s=>s.id===input.restaurantId))throw new Error('Unknown restaurant');go('Explore');openSpot(input.restaurantId);return{restaurantId:input.restaurantId,status:'encounter_opened',demo:true}}})).catch(()=>{});}catch{}}

function startCatchStage(id){
 const s=spots.find(s=>s.id===id);if(!s||mode!=='demo')return;
 modal(`<div class="catch-stage"><div class="catch-top">${closeButton()}<span class="eyebrow">LOG A DEMO BITE</span><h2>${s.name}</h2><p>${s.cuisine} · ${s.area}</p><span class="catch-cp">${s.countryCodes.length?s.countryCodes.map(countryName).join(' + ')+' stamp':'Neighborhood discovery'}</span></div><div class="catch-target"><div class="target-ring"></div><span class="catch-food">${foodArt(s)}</span><span class="target-caption">A cuisine at your table</span></div><div class="catch-bottom"><span class="throw-hint">Toss your token to log this bite</span><button class="bite-token" id="throwToken" aria-label="Throw Bite Token to collect restaurant"><span>b.</span></button><button class="throw-accessible" id="throwButton">Or tap to toss ↗</button><p>Demo log · No real purchase is verified</p></div><div class="catch-sparkles" aria-hidden="true">✦ ✧ ✦ ✧ ✦</div></div>`);dialog.classList.add('catch-dialog');
 const token=document.querySelector('#throwToken');let startY=null,thrown=false;
 const toss=()=>{if(thrown)return;thrown=true;token.disabled=true;document.querySelector('#throwButton').disabled=true;document.querySelector('.catch-stage').classList.add('throwing');document.querySelector('.throw-hint').textContent='Nice toss!';setTimeout(()=>{catchSpot(id)},matchMedia('(prefers-reduced-motion: reduce)').matches?100:1000)};
 token.onpointerdown=e=>{startY=e.clientY;token.setPointerCapture(e.pointerId)};
 token.onpointerup=e=>{if(startY!==null&&(startY-e.clientY>25||Math.abs(startY-e.clientY)<8))toss();startY=null};token.onpointercancel=()=>startY=null;
 token.onclick=e=>{if(e.detail===0)toss()};document.querySelector('#throwButton').onclick=toss;
}

function mapSources(){modal(`<div class="detail-body">${closeButton()}<span class="eyebrow">A REAL NEIGHBORHOOD, A PLAYFUL LENS</span><h2>Built from New York.</h2><p>6,459 building footprints use NYC Open Data roof heights. Eight missing heights use a 12-meter fallback. Windows and facade colors are illustrative, not surveyed.</p><p>Street geometry and parks come from OpenStreetMap. Business coordinates come from NYC restaurant inspection records and NYC address data; pins may not mark the exact entrance.</p><p>All recorded heights are rendered at true scale. Ink outlines, cel shading, facade colors, street markings, and game signs are artistic treatments inspired by retro anime New York.</p><div class="source-links"><a href="https://data.cityofnewyork.us/d/5zhs-2jue" target="_blank" rel="noopener">NYC building footprints & roof heights ↗</a><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL ↗</a><a href="https://data.cityofnewyork.us/d/43nn-pn8j" target="_blank" rel="noopener">NYC business address coordinates ↗</a><a href="https://services5.arcgis.com/GfwWNkhOj9bNBqoJ/arcgis/rest/services/NYC_Borough_Boundary/FeatureServer/0" target="_blank" rel="noopener">NYC shoreline boundary dataset ↗</a></div><p class="fine">Retrieved September 10, 2026. Map data may lag changes. The simulated walking network is not an accessibility or navigation service.</p><h3>Why these businesses?</h3><p>Our picks emphasize neighborhood roots, independent operations, and different food traditions. “Underrated” is a curatorial judgment; we haven’t measured TikTok reach, queues, or popularity.</p><p class="fine">Real businesses have not endorsed Bite Quest. Sample rewards cannot be redeemed there.</p></div>`)}

function countryBadges(){return window.BITE_CONTENT.earned(state,spots)}
function countryName(code){return window.BITE_CONTENT.cuisine(code).label}
function rarityText(code){const r=window.BITE_CONTENT.rarityFor(code);return r.status==='unknown'?'Rarity not assessed':`${r.status==='demo'?'Demo rarity: ':''}${r.name}`}
function badgeToken(code,earned=true){return `<span class="cuisine-stamp ${earned?'is-earned':'is-locked'}"><img data-cuisine-stamp="${code}" data-earned="${earned}" alt="${escapeHTML(countryName(code))} ${earned?'earned':'locked'} food stamp" hidden><span class="stamp-loading">${escapeHTML(countryName(code))}</span></span>`}
function countryLink(code){return `<button class="country-link" data-country="${code}">${countryName(code)} stamp · ${rarityText(code)}</button>`}
function bindCountries(){document.querySelectorAll('[data-country]').forEach(b=>b.onclick=()=>badgeDetail(b.dataset.country))}
function badgeDetail(code){const c=window.BITE_CONTENT.country(code);if(!c)return;const matches=spots.filter(s=>s.countryCodes.includes(code)),earned=countryBadges().includes(code),r=window.BITE_CONTENT.rarityFor(code);modal(`<div class="detail-body story-screen">${closeButton()}${badgeToken(code,earned)}<span class="eyebrow">${earned?'CUISINE STAMP EARNED':'YOUR NEXT CUISINE?'}</span><h2>${countryName(c.code)}</h2><p><strong>${rarityText(code)}</strong></p><p>${r.count===null?'A citywide business count has not been researched.':`${r.count} ${r.status==='demo'?'example':'verified'} NYC ${r.count===1?'business':'businesses'} in the rarity model. ${r.status==='demo'?'DEMO DATA — not a measured NYC count.':''}`}</p><p>${window.BITE_CONTENT.rarity.map(t=>t.name+': '+(t.max===Infinity?'more than '+window.BITE_CONTENT.rarity.at(-2).max:t.max===1?'1':'up to '+t.max)+(t.max===1?' kitchen':' kitchens')).join('. ')}. Rarity measures availability, not quality or popularity.</p><h3>${earned?'Businesses behind your badge':'Find your first bite'}</h3>${matches.length?listSpots(matches):`<p>No researched ${countryName(c.code)} listing yet. This badge is a catalog goal, not a claim that a kitchen exists in NYC.</p><button class="secondary" id="badgeSuggestion">Start with Café Katja’s Austrian cooking</button>`}<p class="fine">Food traditions cross borders. Follow the dish, then meet the kitchen behind it.</p></div>`);bindSpots();document.querySelector('#badgeSuggestion')?.addEventListener('click',()=>openSpot('katja'));}
function trailCard(t){const p=window.BITE_CONTENT.progress(t,state,spots),missing=t.mode==='businesses'?p.missing.map(id=>spots.find(s=>s.id===id)?.name||id):p.missing.map(countryName),fixed=['countries','businesses'].includes(t.mode);return `<article class="card trail-card"><span class="eyebrow">${t.kind}</span><h2>${t.name}</h2><p>${t.description||'Earn the cuisine stamps in this editorial regional set. Cuisine traditions cross borders; these sets are a starting point.'}</p><p><strong>${p.have} / ${p.goal}</strong> ${p.done?'· Complete':'· In progress'}</p><progress value="${p.have}" max="${p.goal}" aria-label="${t.name} progress">${p.have} / ${p.goal}</progress><p><strong>${p.done?'Title earned':'Completion title'}:</strong> ${t.reward}</p>${p.done?'':`<details><summary>${fixed?'Missing badges / businesses':'Next available badges'} (${missing.length})</summary><p>${missing.join(' · ')||'More researched listings are needed.'}</p>${!fixed?`<p>${p.goal-p.have} more distinct cuisines needed. ${missing.length<p.goal-p.have?'The starter list cannot complete this trail yet.':''}</p>`:''}</details>`}<button class="secondary wide" data-trail="${t.id}">${p.done?'See your profile title':'Find a next bite'}</button></article>`}
function bindTrails(){document.querySelectorAll('[data-trail]').forEach(b=>b.onclick=()=>{const t=window.BITE_CONTENT.trails.find(t=>t.id===b.dataset.trail),p=window.BITE_CONTENT.progress(t,state,spots);if(p.done){go('Profile');return}const ids=t.mode==='businesses'?p.missing:spots.filter(s=>s.countryCodes.some(c=>p.missing.includes(c))).map(s=>s.id);if(ids.length)openSpot(ids[0]);else{modal(`<div class="detail-body">${closeButton()}<h2>${t.name}</h2><p>We need more researched businesses to finish this trail.</p><p>Missing: ${p.missing.map(countryName).join(', ')||`${p.goal-p.have} more cuisines`}.</p><button class="primary" id="trailStarter">Try the Three Cuisines starter trail</button></div>`);document.querySelector('#trailStarter').onclick=()=>openSpot('katja');}})}
function wantList(){modal(`<div class="detail-body story-screen">${closeButton()}<h2>Want to try</h2><p>Keep the next kitchen in reach. Saved on this device.</p>${state.wantToTry.length?listSpots(spots.filter(s=>state.wantToTry.includes(s.id))):`<p>Nothing saved yet. Start with Michaeli Bakery’s babka on Division Street.</p><button class="primary" data-spot="michaeli">Meet Michaeli Bakery</button>`}</div>`);bindSpots()}
function sharePreview(kind,featured){
 const earned=countryBadges(),visited=Boolean(state.visits[featured.id]),starter=window.BITE_CONTENT.trails.find(t=>t.id===window.BITE_CONTENT.firstTrailId),progress=window.BITE_CONTENT.progress(starter,state,spots),url=businessURL(featured.id);
 const text=kind==='business'?`${visited?'I just discovered':'I want to try'} ${featured.cuisine} at ${featured.name} in ${featured.area}. Try ${featured.signatureDish}. ${visited?'Bite Quest demo: dining was simulated.':'A place on my want-to-try list.'}`:`My Bite Quest food passport: ${earned.length} cuisine stamps. ${earned.map(countryName).join(', ')}. ${starter.name}: ${progress.have}/${progress.goal}. Come try ${featured.name} in ${featured.area}. Demo dining logs.`;
 if(window.passportObjectURL){URL.revokeObjectURL(window.passportObjectURL);window.passportObjectURL=null;}
 modal(`<div class="detail-body story-screen passport-share">${closeButton()}<span class="eyebrow">GOOD FOOD TRAVELS BY WORD OF MOUTH</span><h2>${kind==='business'?'Send this bite to a friend':'Your passport, ready to share'}</h2><div class="passport-preview" id="passportPreview"><p role="status">Printing your food stamps…</p></div><p id="exportStatus" role="status"></p><div class="controls export-actions"><button class="primary" id="shareImage" disabled>Share image</button><button class="secondary" id="downloadImage" disabled>Download PNG</button><button class="secondary" id="copyBusinessLink">Copy restaurant link</button></div><a class="country-link" href="${url}">Open ${featured.name} ↗</a><details><summary>Message to send with your card</summary><p id="shareCaption">${escapeHTML(text)}</p></details><p class="fine">Illustrated food, not a merchant photo. Demo dining is labeled on the card. If image sharing is unavailable, save the PNG and send it with the restaurant link.</p></div>`);
 const preview=document.querySelector('#passportPreview'),status=document.querySelector('#exportStatus'),shareButton=document.querySelector('#shareImage'),downloadButton=document.querySelector('#downloadImage');
 document.querySelector('#copyBusinessLink').onclick=async()=>{try{await navigator.clipboard.writeText(url);status.textContent='Restaurant link copied.'}catch{status.textContent='Copy this link: '+url}};
 window.BITE_PASSPORT.render({kind,earned,featured,visited,trail:{name:starter.name,...progress}}).then(({blob})=>{if(!preview.isConnected)return;const objectURL=URL.createObjectURL(blob);window.passportObjectURL=objectURL;preview.innerHTML=`<img src="${objectURL}" alt="${kind==='business'?featured.name+' discovery card':'Food passport with '+earned.length+' cuisine stamps'}, featuring ${featured.signatureDish}"><a class="secondary wide" href="${objectURL}" target="_blank" rel="noopener">Open image to save ↗</a>`;const file=new File([blob],kind==='business'?`bite-quest-${featured.id}.png`:'bite-quest-food-passport.png',{type:'image/png'});
 const download=()=>{const a=document.createElement('a');a.href=objectURL;a.download=file.name;document.body.append(a);a.click();a.remove();status.textContent='Download requested. If it does not start, open the image below and save it.'};downloadButton.disabled=false;shareButton.disabled=false;downloadButton.onclick=download;shareButton.onclick=async()=>{try{if(navigator.share&&window.BITE_PASSPORT.delivery(navigator.canShare?.bind(navigator),file)==='native-image'){await navigator.share({title:'Bite Quest — '+featured.name,text,url,files:[file]});status.textContent='Share sheet closed.'}else download()}catch(e){if(e.name==='AbortError')status.textContent='Sharing canceled. Your passport is still ready.';else{status.textContent='Image sharing is unavailable. Use Download PNG or copy the restaurant link.'}}};
 }).catch(()=>{if(preview.isConnected){preview.innerHTML='<p>Your card could not be generated. You can still share the restaurant link.</p>';status.textContent='Reopen this preview to try again.'}});
}
function businessShare(s){sharePreview('business',s)}
function businessURL(id){return 'https://bite-quest-nyc-rm.meyer-rebecca-chs.chatgpt.site/?business='+encodeURIComponent(id)}

const incomingBusiness=new URLSearchParams(location.search).get('business');if(incomingBusiness&&spots.some(s=>s.id===incomingBusiness))openSpot(incomingBusiness);else if(state.storyIntroVersion!==window.BITE_CONTENT.version)onboard();
